### 5.3 DJI On-Board Blackbox (`.DAT`) Framing Iterator

Zero-copy framing iterator over memory-mapped or buffered `.DAT` bytes:

```rust
pub mod dat {
    use super::FlightReaderError;

    /// The synchronization magic byte opening every .DAT frame.
    pub const DAT_MAGIC: u8 = 0x55;

    /// Checksum verification modes for .DAT frames.
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub enum ChecksumType {
        Crc16,
        Crc32,
    }

    /// Represents a zero-copy frame borrowed directly from the stream slice.
    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub struct DatFrame<'a> {
        /// Sequence counter / sub-header flag (offset 0x02).
        pub sequence: u8,
        /// Numerical sensor struct identifier (offsets 0x03..0x04).
        pub payload_id: u16,
        /// Hardware clock counter in microsecond ticks (offsets 0x05..0x08).
        pub timestamp_ticks: u32,
        /// Borrowed raw sensor payload slice (Length - 9 - ChecksumLen bytes).
        pub payload: &'a [u8],
        /// Extracted frame checksum.
        pub checksum: u32,
    }

    /// Streaming zero-allocation iterator over .DAT binary byte streams.
    pub struct DatFrameIterator<'a> {
        stream: &'a [u8],
        cursor: usize,
        checksum_type: ChecksumType,
    }

    impl<'a> DatFrameIterator<'a> {
        /// Creates a new iterator starting at byte offset 0.
        pub fn new(stream: &'a [u8], checksum_type: ChecksumType) -> Self {
            Self {
                stream,
                cursor: 0,
                checksum_type,
            }
        }

        /// Returns the current stream byte position.
        pub fn position(&self) -> usize {
            self.cursor
        }
    }

    impl<'a> Iterator for DatFrameIterator<'a> {
        type Item = Result<DatFrame<'a>, FlightReaderError>;

        fn next(&mut self) -> Option<Self::Item> {
            let chk_len = match self.checksum_type {
                ChecksumType::Crc16 => 2,
                ChecksumType::Crc32 => 4,
            };
            let min_len = 9 + chk_len; // 11 for CRC16, 13 for CRC32

            while self.cursor + 9 <= self.stream.len() {
                // 1. Scan for Magic Byte 0x55
                if self.stream[self.cursor] != DAT_MAGIC {
                    self.cursor += 1;
                    continue;
                }

                // 2. Validate Frame Length Field
                let frame_len = self.stream[self.cursor + 1] as usize;
                if frame_len < min_len {
                    // Invalid frame length noise, skip magic byte and continue searching
                    self.cursor += 1;
                    continue;
                }

                // 3. Check for Buffer Availability
                if self.cursor + frame_len > self.stream.len() {
                    // Stream ends prematurely
                    return None;
                }

                let frame_bytes = &self.stream[self.cursor..self.cursor + frame_len];
                let body = &frame_bytes[..frame_len - chk_len];
                let chk_bytes = &frame_bytes[frame_len - chk_len..];

                // 4. Verify Checksum
                let (is_valid, computed, expected) = match self.checksum_type {
                    ChecksumType::Crc16 => {
                        let expected = u16::from_le_bytes([chk_bytes[0], chk_bytes[1]]) as u32;
                        let computed = checksum::calc_crc16(body, 0x3692) as u32;
                        (computed == expected, computed, expected)
                    }
                    ChecksumType::Crc32 => {
                        let expected = u32::from_le_bytes([
                            chk_bytes[0], chk_bytes[1], chk_bytes[2], chk_bytes[3],
                        ]);
                        let computed = checksum::calc_crc32(body);
                        (computed == expected, computed, expected)
                    }
                };

                let payload_id = u16::from_le_bytes([body[3], body[4]]);

                if !is_valid {
                    let err_offset = self.cursor;
                    self.cursor += 1; // Resynchronize by advancing 1 byte
                    return Some(Err(FlightReaderError::ChecksumMismatch {
                        payload_id,
                        offset: err_offset,
                        computed,
                        expected,
                    }));
                }

                // 5. Successful Frame Parse
                let seq = body[2];
                let ticks = u32::from_le_bytes([body[5], body[6], body[7], body[8]]);
                let payload = &body[9..];

                self.cursor += frame_len;

                return Some(Ok(DatFrame {
                    sequence: seq,
                    payload_id,
                    timestamp_ticks: ticks,
                    payload,
                    checksum: expected,
                }));
            }

            None
        }
    }
}
